        G_f = set()
        for i in range(n):
            for j in range(i+1, n):
                x = sum(1 << k for k in range(n) if f[k] == (i < j))
                y = sum(1 << k for k in range(n) if f[k] == (j < i))
                G_f.add((x, y))
        return len(G_f)

